--
-- Structure for view `class_performance_summary`
--
DROP TABLE IF EXISTS `class_performance_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY INVOKER VIEW `class_performance_summary`  AS SELECT `c`.`id` AS `class_id`, `c`.`name` AS `class_name`, `c`.`level` AS `level`, `cr`.`term` AS `term`, `cr`.`academic_year` AS `academic_year`, count(`cr`.`id`) AS `total_students`, round(avg(`cr`.`average_score`),2) AS `class_average`, max(`cr`.`average_score`) AS `highest_score`, min(`cr`.`average_score`) AS `lowest_score`, count(case when `cr`.`position` = 1 then 1 end) AS `first_position_count` FROM (`classes` `c` left join `compiled_results` `cr` on(`c`.`id` = `cr`.`class_id`)) WHERE `cr`.`status` = 'Approved' GROUP BY `c`.`id`, `c`.`name`, `c`.`level`, `cr`.`term`, `cr`.`academic_year` ;

-- --------------------------------------------------------

--
-- Structure for view `data_changes_summary`
--
DROP TABLE IF EXISTS `data_changes_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `data_changes_summary`  AS SELECT `dcl`.`table_name` AS `table_name`, `dcl`.`action_type` AS `action_type`, `dcl`.`username` AS `username`, `dcl`.`user_role` AS `user_role`, `dcl`.`created_at` AS `created_at`, `dcl`.`ip_address` AS `ip_address`, count(0) AS `change_count` FROM `data_change_logs` AS `dcl` WHERE `dcl`.`created_at` >= current_timestamp() - interval 7 day GROUP BY `dcl`.`table_name`, `dcl`.`action_type`, `dcl`.`username`, `dcl`.`user_role`, `dcl`.`created_at`, `dcl`.`ip_address` ORDER BY `dcl`.`created_at` DESC ;

-- --------------------------------------------------------

--
-- Structure for view `security_events_summary`
--
DROP TABLE IF EXISTS `security_events_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `security_events_summary`  AS SELECT `sl`.`username` AS `username`, `sl`.`user_role` AS `user_role`, `sl`.`event_type` AS `event_type`, `sl`.`created_at` AS `created_at`, json_extract(`sl`.`details`,'$.reason') AS `reason`, `sl`.`ip_address` AS `ip_address` FROM `security_logs` AS `sl` WHERE `sl`.`created_at` >= current_timestamp() - interval 24 hour ORDER BY `sl`.`created_at` DESC ;

-- --------------------------------------------------------

