S `domain_name`,`p`.`considerate_of_others` AS `score`,`p`.`considerate_of_others_remark` AS `comment`,`p`.`student_id` AS `student_id`,`p`.`class_id` AS `class_id`,`p`.`term` AS `term`,`p`.`academic_year` AS `academic_year` from `psychomotor_domains` `p` union all select 'Psychomotor' AS `domain_type`,'Handwriting' AS `domain_name`,`p`.`handwriting` AS `score`,`p`.`handwriting_remark` AS `comment`,`p`.`student_id` AS `student_id`,`p`.`class_id` AS `class_id`,`p`.`term` AS `term`,`p`.`academic_year` AS `academic_year` from `psychomotor_domains` `p` union all select 'Psychomotor' AS `domain_type`,'Sports' AS `domain_name`,`p`.`sports` AS `score`,`p`.`sports_remark` AS `comment`,`p`.`student_id` AS `student_id`,`p`.`class_id` AS `class_id`,`p`.`term` AS `term`,`p`.`academic_year` AS `academic_year` from `psychomotor_domains` `p` union all select 'Psychomotor' AS `domain_type`,'Verbal Fluency' AS `domain_name`,`p`.`verbal_fluency` AS `score`,`p`.`verbal_fluency_remark` AS `comment`,`p`.`student_id` AS `student_id`,`p`.`class_id` AS `class_id`,`p`.`term` AS `term`,`p`.`academic_year` AS `academic_year` from `psychomotor_domains` `p` union all select 'Psychomotor' AS `domain_type`,'Works Well Independently' AS `domain_name`,`p`.`works_well_independently` AS `score`,`p`.`works_well_independently_remark` AS `comment`,`p`.`student_id` AS `student_id`,`p`.`class_id` AS `class_id`,`p`.`term` AS `term`,`p`.`academic_year` AS `academic_year` from `psychomotor_domains` `p`  ;

